6	
7	import {
8	  sanitizeEnvironment,
9	  type EnvironmentSanitizationConfig,
10	} from './environmentSanitization.js';
11	
12	/**
13	 * Request for preparing a command to run in a sandbox.
14	 */
15	export interface SandboxRequest {
16	  /** The program to execute. */
17	  command: string;
18	  /** Arguments for the program. */
19	  args: string[];
20	  /** The working directory. */
21	  cwd: string;
22	  /** Environment variables to be passed to the program. */
23	  env: NodeJS.ProcessEnv;
24	  /** Optional sandbox-specific configuration. */
25	  config?: {
26	    sanitizationConfig?: Partial<EnvironmentSanitizationConfig>;
27	  };
28	}
29	
30	/**
31	 * A command that has been prepared for sandboxed execution.
32	 */
33	export interface SandboxedCommand {
34	  /** The program or wrapper to execute. */
35	  program: string;
36	  /** Final arguments for the program. */
37	  args: string[];
38	  /** Sanitized environment variables. */
39	  env: NodeJS.ProcessEnv;
40	  /** The working directory. */
41	  cwd?: string;
42	}
43	
44	/**
45	 * Interface for a service that prepares commands for sandboxed execution.
46	 */
47	export interface SandboxManager {
48	  /**
49	   * Prepares a command to run in a sandbox, including environment sanitization.
50	   */
51	  prepareCommand(req: SandboxRequest): Promise<SandboxedCommand>;
52	}
53	
54	/**
55	 * A no-op implementation of SandboxManager that silently passes commands
56	 * through while applying environment sanitization.
57	 */
58	export class NoopSandboxManager implements SandboxManager {
59	  /**
60	   * Prepares a command by sanitizing the environment and passing through
61	   * the original program and arguments.
62	   */
63	  async prepareCommand(req: SandboxRequest): Promise<SandboxedCommand> {
64	    const sanitizationConfig: EnvironmentSanitizationConfig = {
65	      allowedEnvironmentVariables:
66	        req.config?.sanitizationConfig?.allowedEnvironmentVariables ?? [],
67	      blockedEnvironmentVariables:
68	        req.config?.sanitizationConfig?.blockedEnvironmentVariables ?? [],
69	      enableEnvironmentVariableRedaction:
70	        req.config?.sanitizationConfig?.enableEnvironmentVariableRedaction ??
71	        true,
72	    };
73	
74	    const sanitizedEnv = sanitizeEnvironment(req.env, sanitizationConfig);
75	
76	    return {
77	      program: req.command,
78	      args: req.args,
79	      env: sanitizedEnv,
80	    };
81	  }
82	}
83	
84	/**
85	 * SandboxManager that implements actual sandboxing.
86	 */
87	export class LocalSandboxManager implements SandboxManager {
88	  async prepareCommand(_req: SandboxRequest): Promise<SandboxedCommand> {
89	    throw new Error('Tool sandboxing is not yet implemented.');
90	  }
91	}
92	
93	/**
94	 * Creates a sandbox manager based on the provided settings.
95	 */
96	export function createSandboxManager(
97	  sandboxingEnabled: boolean,
98	): SandboxManager {
99	  if (sandboxingEnabled) {
100	    return new LocalSandboxManager();
101	  }
102	  return new NoopSandboxManager();
103	}
