7	import { describe, expect, it } from 'vitest';
8	import {
9	  ALWAYS_ALLOWED_ENVIRONMENT_VARIABLES,
10	  NEVER_ALLOWED_ENVIRONMENT_VARIABLES,
11	  NEVER_ALLOWED_NAME_PATTERNS,
12	  NEVER_ALLOWED_VALUE_PATTERNS,
13	  sanitizeEnvironment,
14	} from './environmentSanitization.js';
15	
16	const EMPTY_OPTIONS = {
17	  allowedEnvironmentVariables: [],
18	  blockedEnvironmentVariables: [],
19	  enableEnvironmentVariableRedaction: true,
20	};
21	
22	describe('sanitizeEnvironment', () => {
23	  it('should allow safe, common environment variables', () => {
24	    const env = {
25	      PATH: '/usr/bin',
26	      HOME: '/home/user',
27	      USER: 'user',
28	      SystemRoot: 'C:\\Windows',
29	      LANG: 'en_US.UTF-8',
30	    };
31	    const sanitized = sanitizeEnvironment(env, EMPTY_OPTIONS);
32	    expect(sanitized).toEqual(env);
33	  });
34	
35	  it('should allow TERM and COLORTERM environment variables', () => {
36	    const env = {
37	      TERM: 'xterm-256color',
38	      COLORTERM: 'truecolor',
39	    };
40	    const sanitized = sanitizeEnvironment(env, EMPTY_OPTIONS);
41	    expect(sanitized).toEqual(env);
42	  });
43	
44	  it('should preserve TERM and COLORTERM even in strict sanitization mode', () => {
45	    const env = {
46	      GITHUB_SHA: 'abc123',
47	      TERM: 'xterm-256color',
48	      COLORTERM: 'truecolor',
49	      SOME_OTHER_VAR: 'value',
50	    };
51	    const sanitized = sanitizeEnvironment(env, EMPTY_OPTIONS);
52	    expect(sanitized).toEqual({
53	      TERM: 'xterm-256color',
54	      COLORTERM: 'truecolor',
55	    });
56	  });
57	
58	  it('should allow variables prefixed with GEMINI_CLI_', () => {
59	    const env = {
60	      GEMINI_CLI_FOO: 'bar',
61	      GEMINI_CLI_BAZ: 'qux',
62	    };
63	    const sanitized = sanitizeEnvironment(env, EMPTY_OPTIONS);
64	    expect(sanitized).toEqual(env);
65	  });
66	
67	  it('should redact variables with sensitive names from the denylist', () => {
68	    const env = {
69	      CLIENT_ID: 'sensitive-id',
70	      DB_URI: 'sensitive-uri',
71	      DATABASE_URL: 'sensitive-url',
72	      SAFE_VAR: 'is-safe',
73	    };
74	    const sanitized = sanitizeEnvironment(env, EMPTY_OPTIONS);
75	    expect(sanitized).toEqual({
76	      SAFE_VAR: 'is-safe',
77	    });
78	  });
79	
80	  it('should redact variables with names matching all sensitive patterns (case-insensitive)', () => {
81	    const env = {
82	      // Patterns
83	      MY_API_TOKEN: 'token-value',
84	      AppSecret: 'secret-value',
85	      db_password: 'password-value',
86	      ORA_PASSWD: 'password-value',
87	      ANOTHER_KEY: 'key-value',
88	      some_auth_var: 'auth-value',
89	      USER_CREDENTIAL: 'cred-value',
90	      AWS_CREDS: 'creds-value',
91	      PRIVATE_STUFF: 'private-value',
92	      SSL_CERT: 'cert-value',
93	      // Safe variable
94	      USEFUL_INFO: 'is-ok',
95	    };
96	    const sanitized = sanitizeEnvironment(env, EMPTY_OPTIONS);
97	    expect(sanitized).toEqual({
98	      USEFUL_INFO: 'is-ok',
99	    });
100	  });
101	
102	  it('should redact variables with values matching all private key patterns', () => {
103	    const env = {
104	      RSA_KEY: '-----BEGIN RSA PRIVATE KEY-----...',
105	      OPENSSH_KEY: '-----BEGIN OPENSSH PRIVATE KEY-----...',
106	      EC_KEY: '-----BEGIN EC PRIVATE KEY-----...',
107	      PGP_KEY: '-----BEGIN PGP PRIVATE KEY-----...',
108	      CERTIFICATE: '-----BEGIN CERTIFICATE-----...',
109	      SAFE_VAR: 'is-safe',
110	    };
111	    const sanitized = sanitizeEnvironment(env, EMPTY_OPTIONS);
112	    expect(sanitized).toEqual({
113	      SAFE_VAR: 'is-safe',
114	    });
115	  });
116	
117	  it('should redact variables with values matching all token and credential patterns', () => {
118	    const env = {
119	      // GitHub
120	      GITHUB_TOKEN_GHP: 'ghp_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx',
121	      GITHUB_TOKEN_GHO: 'gho_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx',
122	      GITHUB_TOKEN_GHU: 'ghu_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx',
123	      GITHUB_TOKEN_GHS: 'ghs_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx',
124	      GITHUB_TOKEN_GHR: 'ghr_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx',
125	      GITHUB_PAT: 'github_pat_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx',
126	      // Google
127	      GOOGLE_KEY: 'AIzaSyxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx',
128	      // AWS
129	      AWS_KEY: 'AKIAxxxxxxxxxxxxxxxx',
130	      // JWT
131	      JWT_TOKEN: 'eyJhbGciOiJIUzI1NiJ9.e30.ZRrHA157xAA_7962-a_3rA',
132	      // Stripe
133	      STRIPE_SK_LIVE: 'sk_live_xxxxxxxxxxxxxxxxxxxxxxxx',
134	      STRIPE_RK_LIVE: 'rk_live_xxxxxxxxxxxxxxxxxxxxxxxx',
135	      STRIPE_SK_TEST: 'sk_test_xxxxxxxxxxxxxxxxxxxxxxxx',
136	      STRIPE_RK_TEST: 'rk_test_xxxxxxxxxxxxxxxxxxxxxxxx',
137	      // Slack
138	      SLACK_XOXB: 'xoxb-xxxxxxxxxxxx-xxxxxxxxxxxx-xxxxxxxx',
139	      SLACK_XOXA: 'xoxa-xxxxxxxxxxxx-xxxxxxxxxxxx-xxxxxxxx',
140	      SLACK_XOXP: 'xoxp-xxxxxxxxxxxx-xxxxxxxxxxxx-xxxxxxxx',
141	      SLACK_XOXB_2: 'xoxr-xxxxxxxxxxxx-xxxxxxxxxxxx-xxxxxxxx',
142	      // URL Credentials
143	      CREDS_IN_HTTPS_URL: 'https://user:password@example.com',
144	      CREDS_IN_HTTP_URL: 'http://user:password@example.com',
145	      CREDS_IN_FTP_URL: 'ftp://user:password@example.com',
146	      CREDS_IN_SMTP_URL: 'smtp://user:password@example.com',
147	      // Safe variable
148	      SAFE_VAR: 'is-safe',
149	    };
150	    const sanitized = sanitizeEnvironment(env, EMPTY_OPTIONS);
151	    expect(sanitized).toEqual({
152	      SAFE_VAR: 'is-safe',
153	    });
154	  });
155	
156	  it('should not redact variables that look similar to sensitive patterns', () => {
157	    const env = {
158	      // Not a credential in URL
159	      SAFE_URL: 'https://example.com/foo/bar',
160	      // Not a real JWT
161	      NOT_A_JWT: 'this.is.not.a.jwt',
162	      // Too short to be a token
163	      ALMOST_A_TOKEN: 'ghp_12345',
164	      // Contains a sensitive word, but in a safe context in the value
165	      PUBLIC_KEY_INFO: 'This value describes a public key',
166	      // Variable names that could be false positives
167	      KEYNOTE_SPEAKER: 'Dr. Jane Goodall',
168	      CERTIFIED_DIVER: 'true',
169	      AUTHENTICATION_FLOW: 'oauth',
170	      PRIVATE_JET_OWNER: 'false',
171	    };
172	    const sanitized = sanitizeEnvironment(env, EMPTY_OPTIONS);
173	    expect(sanitized).toEqual({
174	      SAFE_URL: 'https://example.com/foo/bar',
175	      NOT_A_JWT: 'this.is.not.a.jwt',
176	    });
177	  });
178	
179	  it('should not redact variables with undefined or empty values if name is safe', () => {
180	    const env: NodeJS.ProcessEnv = {
181	      EMPTY_VAR: '',
182	      UNDEFINED_VAR: undefined,
183	      ANOTHER_SAFE_VAR: 'value',
184	    };
185	    const sanitized = sanitizeEnvironment(env, EMPTY_OPTIONS);
186	    expect(sanitized).toEqual({
187	      EMPTY_VAR: '',
188	      ANOTHER_SAFE_VAR: 'value',
189	    });
190	  });
191	
192	  it('should allow variables that do not match any redaction rules', () => {
193	    const env = {
194	      NODE_ENV: 'development',
195	      APP_VERSION: '1.0.0',
196	    };
197	    const sanitized = sanitizeEnvironment(env, EMPTY_OPTIONS);
198	    expect(sanitized).toEqual(env);
199	  });
200	
