 * Builds a sanitization configuration that guarantees environment variable
 * redaction is always enforced.
 *
 * The allowed and blocked lists from both `requestedConfig` and `baseConfig`
 * are merged. Any allowed variable that is known to be sensitive (either
 * listed in {@link NEVER_ALLOWED_ENVIRONMENT_VARIABLES} or matching one of the
 * {@link NEVER_ALLOWED_NAME_PATTERNS}) is stripped from the allowed list so it
 * can never be un-redacted via configuration. Both lists are deduplicated.
 */
export function getSecureSanitizationConfig(
  requestedConfig?: Partial<EnvironmentSanitizationConfig>,
  baseConfig?: Partial<EnvironmentSanitizationConfig>,
): EnvironmentSanitizationConfig {
  const mergedAllowed = [
    ...(baseConfig?.allowedEnvironmentVariables ?? []),
    ...(requestedConfig?.allowedEnvironmentVariables ?? []),
  ];
  const mergedBlocked = [
    ...(baseConfig?.blockedEnvironmentVariables ?? []),
    ...(requestedConfig?.blockedEnvironmentVariables ?? []),
  ];

  const filteredAllowed = mergedAllowed.filter((name) => {
    const upper = name.toUpperCase();
    if (NEVER_ALLOWED_ENVIRONMENT_VARIABLES.has(upper)) {
      return false;
    }
    for (const pattern of NEVER_ALLOWED_NAME_PATTERNS) {
      if (pattern.test(name)) {
        return false;
      }
    }
    return true;
  });

  return {
    allowedEnvironmentVariables: dedupe(filteredAllowed),
    blockedEnvironmentVariables: dedupe(mergedBlocked),
    enableEnvironmentVariableRedaction: true,
  };
}

function dedupe(values: string[]): string[] {
  const seen = new Set<string>();
  const result: string[] = [];
  for (const value of values) {
    if (!seen.has(value)) {
      seen.add(value);
      result.push(value);
    }
  }
  return result;
}

