import {
  type SandboxManager,
  type SandboxRequest,
  type SandboxedCommand,
} from '../../services/sandboxManager.js';
import {
  sanitizeEnvironment,
  getSecureSanitizationConfig,
  type EnvironmentSanitizationConfig,
} from '../../services/environmentSanitization.js';

export interface LinuxSandboxOptions {
  workspace: string;
  allowedPaths?: string[];
  sanitizationConfig?: EnvironmentSanitizationConfig;
}

export class LinuxSandboxManager implements SandboxManager {
  constructor(private readonly options: LinuxSandboxOptions) {}

  async prepareCommand(req: SandboxRequest): Promise<SandboxedCommand> {
    const sanitizationConfig = getSecureSanitizationConfig(
      req.config?.sanitizationConfig,
      this.options.sanitizationConfig,
    );

    const sanitizedEnv = sanitizeEnvironment(req.env, sanitizationConfig);

    const bwrapArgs: string[] = [
      '--unshare-all',
      '--new-session',
      '--die-with-parent',
      '--ro-bind',
      '/',
      '/',
      '--dev',
      '/dev',
      '--proc',
      '/proc',
      '--tmpfs',
      '/tmp',
      '--bind',
      this.options.workspace,
      this.options.workspace,
    ];

    const allowedPaths = this.options.allowedPaths ?? [];
    for (const path of allowedPaths) {
      if (path !== this.options.workspace) {
        bwrapArgs.push('--bind', path, path);
      }
    }

    bwrapArgs.push('--', req.command, ...req.args);

    return {
      program: 'bwrap',
      args: bwrapArgs,
      env: sanitizedEnv,
    };
  }
}
```

**Note:** The inline comments (from the diff) explain that `--new-session` performs `"Isolate session"`, `--die-with-parent` is meant to `"Prevent orphaned runaway processes"`, `--dev` `"Creates a safe, minimal /dev (replaces --dev-bind)"`, `--proc` `"Creates a fresh procfs for the unshared PID namespace"`, and `--tmpfs` `"Provides an isolated, writable /tmp directory"`.

## Exact bwrap Args Order

1. `--unshare-all`
2. `--new-session`
3. `--die-with-parent`
4. `--ro-bind` / `/` / `/`
5. `--dev` / `/dev`
6. `--proc` / `/proc`
7. `--tmpfs` / `/tmp`
8. `--bind` / workspace / workspace
9. (loop) `--bind` / path / path for each allowedPath ≠ workspace
10. `--` / command / ...args

## getSecureSanitizationConfig (from environmentSanitization.ts)

```typescript
export function getSecureSanitizationConfig(
  requestedConfig: Partial<EnvironmentSanitizationConfig> = {},
  baseConfig?: EnvironmentSanitizationConfig,
): EnvironmentSanitizationConfig {
  const allowed = [
    ...(baseConfig?.allowedEnvironmentVariables ?? []),
    ...(requestedConfig.allowedEnvironmentVariables ?? []),
  ].filter((key) => {
    const upperKey = key.toUpperCase();
    if (NEVER_ALLOWED_ENVIRONMENT_VARIABLES.has(upperKey)) {
      return false;
    }
    for (const pattern of NEVER_ALLOWED_NAME_PATTERNS) {
      if (pattern.test(upperKey)) {
        return false;
      }
    }
    return true;
  });

  const blocked = [
    ...(baseConfig?.blockedEnvironmentVariables ?? []),
    ...(requestedConfig.blockedEnvironmentVariables ?? []),
  ];

  return {
    allowedEnvironmentVariables: [...new Set(allowed)],
    blockedEnvironmentVariables: [...new Set(blocked)],
    enableEnvironmentVariableRedaction: true,
  };
}
```

Key behaviors: merges base + requested allow/block lists, filters names in the never-allowed set/patterns, deduplicates via `Set`, and always forces redaction enabled.

## Test Expectations for bwrap Args

**Test 1** — basic command (`ls -la`) expects `program` `"bwrap"` and args exactly:
```
['--unshare-all','--new-session','--die-with-parent','--ro-bind','/','/',
 '--dev','/dev','--proc','/proc','--tmpfs','/tmp',
 '--bind', workspace, workspace, '--','ls','-la']
```

**Test 2** — with `allowedPaths: ['/tmp/cache', '/opt/tools', workspace]` running `node script.js` expects the same prefix, then the appended binds (workspace excluded from the loop since it's already bound):
```
...'--bind', workspace, workspace,
'--bind','/tmp/cache','/tmp/cache',
'--bind','/opt/tools','/opt/tools',
'--','node','script.js']
```

The workspace, though present in `allowedPaths`, is not re-bound in the loop, confirming the `path !== workspace` guard.

