import {
  getSecureSanitizationConfig,
  sanitizeEnvironment,
  type EnvironmentSanitizationConfig,
} from '../../services/environmentSanitization.js';

/**
 * Options for constructing a {@link LinuxSandboxManager}.
 */
export interface LinuxSandboxOptions {
  /** The workspace directory to bind read/write into the sandbox. */
  workspace: string;
  /** Additional paths to bind into the sandbox. */
  allowedPaths?: string[];
  /** Base environment sanitization configuration. */
  sanitizationConfig?: EnvironmentSanitizationConfig;
}

/**
 * A SandboxManager that provides OS-level isolation on Linux using
 * Bubblewrap (bwrap).
 */
export class LinuxSandboxManager implements SandboxManager {
  constructor(private readonly options: LinuxSandboxOptions) {}

  async prepareCommand(req: SandboxRequest): Promise<SandboxedCommand> {
    const sanitizationConfig = getSecureSanitizationConfig(
      req.config?.sanitizationConfig,
      this.options.sanitizationConfig,
    );

    const sanitizedEnv = sanitizeEnvironment(req.env, sanitizationConfig);

    const bwrapArgs: string[] = [
      '--unshare-all',
      // Isolate session.
      '--new-session',
      // Prevent orphaned runaway processes.
      '--die-with-parent',
      '--ro-bind',
      '/',
      '/',
      // Creates a safe, minimal /dev (replaces --dev-bind).
      '--dev',
      '/dev',
      // Creates a fresh procfs for the unshared PID namespace.
      '--proc',
      '/proc',
      // Provides an isolated, writable /tmp directory.
      '--tmpfs',
      '/tmp',
      '--bind',
      this.options.workspace,
      this.options.workspace,
    ];

    const allowedPaths = this.options.allowedPaths ?? [];
    for (const path of allowedPaths) {
      if (path !== this.options.workspace) {
        bwrapArgs.push('--bind', path, path);
      }
    }

    bwrapArgs.push('--', req.command, ...req.args);

    return {
      program: 'bwrap',
      args: bwrapArgs,
      env: sanitizedEnv,
    };
